values ('1ca5f186-8e35-5b85-90aa-e0b87202c671', '7fdf8f6f-00f4-523c-8501-f9f88ceae74d', 'KR2', 'Хариуцсан тайлантай холбоотой батлагдсан өөрчлөлтийн санал (change proposal)-ын хэрэгжилтийг \[0%→100%\] болгож 2026-09-28-ны дотор хангана.', 'Хариуцсан тайлан бүрийн document/process gap analysis хийж, шаардлагатай өөрчлөлтийн санал (change proposal)-ыг боловсруулж, СГУГ болон холбогдох нэгжтэй review хийлгэнэ. Review-ийн тайлбарыг тусган батлагдсан change proposal-уудын хэрэгжилтийн хуваарийн драфт гаргаж, СГУГ болон холбогдох нэгжийн захиралд ахин хянуулна. Батлагдсан proposal болон хэрэгжилтийн хяналтын баримтыг ХОБПХГ-ийн газрын захиралд хүлээлгэж өгнө.    Secondary indicators (харах зориулалттай, үнэлгээний гол шалгуур биш):  • Change proposal тоо: тайлан бүрт ≥1  • Холбогдох нэгжийн хүлээн авалт: 100%', 30.0,
  '0%→100%\', 'Биелсэн гэж үзэх нөхцөл:  Хариуцсан тайлантай холбоотой бүх батлагдсан change proposal хэрэгжиж, ХОБПХГ-ийн газрын захирлаар хянагдсан байна.    Тооцох аргачлал:  Томьёо: Change Implementation Rate = (Хэрэгжсэн change proposal / Нийт батлагдсан proposal) × 100%    Шаталсан үнэлгээ:  100%: Бүх батлагдсан proposal хэрэгжсэн.  50%: 50%–99% proposal хэрэгжсэн.  0%: 50%-аас доош proposal хэрэгжсэн, эсвэл evidence дутуу.    Evidence: DOC-0035 Policy & Standard & Procedure Set; DOC-0070 Registers & Logs; Change proposal log', '2026-09-28', 'NOT_STARTED');

insert into key_results (id, objective_id, kr_code, title, description, weight,
  target_description, measurement_method, deadline, status)
values ('f7bd33b8-0e50-5f5b-8816-bac443451a6a', '7fdf8f6f-00f4-523c-8501-f9f88ceae74d', 'KR3', 'C-Level-ийн хариуцсан event/committee/OKR schedule-ийн нэгдсэн календарийн хамрагдалтыг \[0%→100%\] болгож 2026-09-30-ны дотор хангана.', 'C-Level-ийн Q3-д хариуцсан event, committee болон OKR schedule-ийг цуглуулж, нэгдсэн календарийн template болон action tracker-ийг боловсруулж, C-Level хариуцагчид болон СГУГ-тай review хийлгэнэ. Review-ийн тайлбарыг тусган Q3-ийн нэгдсэн календарийн драфт болон action list гаргаж, C-Level-ийн захиралд ахин хянуулна. Баталгаажсан нэгдсэн календарийг ХОБПХГ-ийн газрын захиралд хүлээлгэж өгч, Q3-ийн туршид action closure-ыг долоо хоног тутам хянана.    Secondary indicators (харах зориулалттай, үнэлгээний гол шалгуур биш):  • Action closure rate: 100%  • Календарийн шинэчлэлт давтамж: долоо хоног тутам', 20.0,
  '0%→100%\', 'Биелсэн гэж үзэх нөхцөл:  C-Level-ийн Q3-д товлогдсон event/committee/OKR schedule-ийн 100% нэгдсэн календарьт бүртгэгдэж, ХОБПХГ-ийн газрын захирлаар хянагдсан байна.    Тооцох аргачлал:  Томьёо: Calendar Coverage = (Нэгдсэн календарьт бүртгэгдсэн event тоо / Нийт товлогдсон event тоо) × 100%    Шаталсан үнэлгээ:  100%: Бүх event/schedule нэгдсэн календарьт бүртгэгдсэн.  50%: 50%–99% event бүртгэгдсэн.  0%: 50%-аас доош event бүртгэгдсэн, эсвэл evidence дутуу.    Evidence: DOC-0103 Management Pack; DOC-0070 Registers & Logs; C-Level calendar log', '2026-09-30', 'NOT_STARTED');

insert into key_results (id, objective_id, kr_code, title, description, weight,
  target_description, measurement_method, deadline, status)
values ('7386df7c-8f00-5d3a-8d3c-5ee7109f789e', '7fdf8f6f-00f4-523c-8501-f9f88ceae74d', 'KR4', 'Хариуцсан нэгжийн ажилтнуудын Claude сургалтын хамрагдалтыг \[0%→≥95%\] болгож 2026-09-30-ны дотор хангана.', 'Хариуцсан нэгжийн ажилтнуудад зориулан Claude суурь болон role-based сургалтын агуулга, хуваарь болон хамрагдуулах ажилтнуудын жагсаалтыг боловсруулж, СГУГ болон ХОБПХГ-ийн захиралтай review хийлгэнэ. Review-ийн тайлбарыг тусган сургалтын хөтөлбөр болон хамрагдалт хянах механизмын драфт гаргаж, СГУГ-д ахин хянуулна. Сургалтын дүн болон хамрагдалтын тайланг ХОБПХГ-ийн газрын захиралд хүлээлгэж өгнө.    Secondary indicators (харах зориулалттай, үнэлгээний гол шалгуур биш):  • Сургалт дуусгасан ажилтны тоо: нийт ≥95%  • Post-assessment дүн: ≥70%', 20.0,
  '0%→≥95%\', 'Биелсэн гэж үзэх нөхцөл:  Хариуцсан нэгжийн нийт ажилтны 95% буюу дээш нь Claude сургалтад хамрагдаж дуусгасан, ХОБПХГ-ийн газрын захирлаар хянагдсан байна.    Тооцох аргачлал:  Томьёо: Training Completion Rate = (Сургалт дуусгасан ажилтны тоо / Нийт ажилтны тоо) × 100%    Шаталсан үнэлгээ:  100%: ≥95% ажилтан сургалтад хамрагдаж дуусгасан.  50%: 70%–94.9% ажилтан хамрагдсан.  0%: 70%-аас доош ажилтан хамрагдсан, эсвэл evidence дутуу.    Evidence: DOC-0117 Experiment Registry; DOC-0070 Registers & Logs; Сургалтын бүртгэл болон attendance log', '2026-09-30', 'NOT_STARTED');

